/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"bassstation-level-3","number":3,"title":"Audio Monitoring, Patch Management & Basic Performance","skillBand":"Textbook","duration":"From the course textbook","summary":"- Configure an isolated, gain-staged physical audio monitoring path using either the ¼\" mono Line Output or the ¼\" stereo Headphone jack. - Execute the standard safe power-on verification sequence, confirming hardware boot to Patch 0.","modules":[{"id":"bassstation-m-3-1","code":"3","title":"Audio Monitoring, Patch Management & Basic Performance","blurb":"- Configure an isolated, gain-staged physical audio monitoring path using either the ¼\" mono Line Output or the ¼\" stereo Headphone jack. - Execute the standard safe power-on verification sequence, confirming hardware boot to Patch 0.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"bassstation-l-o-3","title":"Section overview","blocks":[{"type":"step","title":"Section 3.1 — Establishing the First Audio Path","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Configure an isolated, gain-staged physical audio monitoring path using either the ¼\" mono Line Output or the ¼\" stereo Headphone jack.","Execute the standard safe power-on verification sequence, confirming hardware boot to Patch <code>0</code>.","Apply acoustic protection protocols against the Bass Station II's high-output headphone amplifier stage."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-3-1-1","title":"3.1.1: Standalone Hardware Audio Connection","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"To establish the initial audio monitoring chain without a host computer:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[Bass Station II]\n  ├── POWER IN ◄── 9 V DC PSU (Centre-Positive)\n  └── LINE OUTPUT (MONO) ──► ¼\" TS Cable ──► Mono Channel (Audio Interface / Mixer / Amp)</pre>"},{"type":"list","items":["<strong>Physical Cable Interface</strong>:","The <code>LINE OUTPUT</code> requires a standard <strong>¼\" (6.35 mm) TS (Tip-Sleeve) unbalanced</strong> instrument or line cable.","Connect the output to a dedicated mono input channel on an audio interface, mixing console, or powered studio monitor.","<strong>Boot Routine</strong>:","Ensure the Master <strong>Volume</strong> knob is set fully counter-clockwise (zero).","Set the rear power slide switch to <code>ext DC</code>.","The 3-character display temporarily illuminates all segments and shows the firmware version before settling stably on <code>0</code> (indicating Patch 0 is active)."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Connect the ¼\" TS cable to an audio interface input set to Line level.","Power on the synthesizer; verify the display reads <code>0</code>.","Strike Middle C repeatedly while slowly raising the <strong>Volume</strong> control to 10 o'clock.","Verify a clean, distortion-free audio signal on your monitoring meters."],"ordered":true}]},{"type":"step","title":"3. Self-Assessment Checkpoint","blocks":[{"type":"list","items":["[ ] What cable type is required to connect the Bass Station II Line Output to an audio interface?","[ ] What patch number does the synthesizer automatically load upon initial power-on?"],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-3-1-2","title":"3.1.2: Headphone Signal Path and Output Coupling","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Connector Architecture</strong>:","The <code>HEADPHONES</code> jack is a <strong>¼\" (6.35 mm) TRS (Tip-Ring-Sleeve)</strong> stereo connector.","The monophonic output of the VCA is routed in parallel to both the Tip (Left) and Ring (Right) contacts, providing a dual-mono acoustic image across standard stereo headphones.","<strong>Parallel Output Interaction</strong>:","The headphone amplifier circuit operates in parallel with the main <code>LINE OUTPUT</code>.","Adjusting the front-panel <strong>Volume</strong> potentiometer scales the output level of <strong>both</strong> the headphone jack and the line output jack simultaneously.","Inserting a headphone plug does not disconnect or mute the line output."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Plug standard studio headphones (using a ¼\" stereo adapter if necessary) into the <code>HEADPHONES</code> jack.","Raise Volume to a comfortable level and play several notes; confirm equal audio distribution in both left and right ears."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-3-1-3","title":"3.1.3: High Output Level and Transducer Safety","blocks":[{"type":"step","title":"3.1.3: High Output Level and Transducer Safety","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"prose","html":"The internal headphone amplifier circuit is engineered to drive high-impedance studio headphones (up to 250–600 Ω)."},{"type":"list","items":["When low-impedance consumer headphones (16–32 Ω) or in-ear monitors (IEMs) are connected, the amplifier can deliver sound pressure levels (SPL) exceeding 115 dB at relatively low knob positions.","Sudden increases in resonance, oscillator overdrive, or accidental patch changes can result in instantaneous volume jumps capable of causing acoustic trauma or damaging headphone driver membranes."],"ordered":false},{"type":"heading","text":"2. Safety Rule","level":4},{"type":"callout","variant":"key","title":"Note","html":"[!CAUTION] Never put on headphones before turning the Volume potentiometer to zero. Raise Volume only while actively triggering a test note."}]},{"type":"step","title":"Section 3.2 — Loading and Saving Patches","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Navigate all 128 internal patch memory locations (<code>0</code> to <code>127</code>).","Differentiate between pre-loaded Factory Patches (<code>0</code> to <code>63</code>) and user Init slots (<code>64</code> to <code>127</code>).","Execute safe patch saving, overwrite avoidance, and save-abort routines.","Understand the non-volatile memory structure and the behavior of the active edit buffer."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-3-2-1","title":"3.2.1: Patch Memory Map: Factory vs. User Space","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The Bass Station II features 128 total non-volatile onboard patch memory slots:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                         128-PATCH MEMORY ALLOCATION                         │\n├──────────────────────────────────────┬──────────────────────────────────────┤\n│ Slots 0 to 63 (Factory Presets)      │ Slots 64 to 127 (User Sound Design)  │\n├──────────────────────────────────────┼──────────────────────────────────────┤\n│ • Pre-loaded with factory patches    │ • Factory-loaded with standard Init  │\n│ • Fully rewritable by the user       │ • Intended for original patch storage│\n│ • Restorable via Components / SysEx  │ • Blank canvas for custom sound design│\n└──────────────────────────────────────┴──────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Factory Slots (<code>0</code>–<code>63</code>)</strong>: Pre-programmed with factory leads, basses, arpeggios, and sound effects. Although factory-loaded, these slots are not write-protected and can be overwritten by the user.","<strong>User Slots (<code>64</code>–<code>127</code>)</strong>: Factory-loaded with the standardized <strong>Init Patch</strong> (a raw single-sawtooth baseline).","<strong>Factory Restoration</strong>: If factory presets (<code>0</code>–<code>63</code>) are overwritten, the original factory soundset can be restored at any time via Novation Components or SysEx import."],"ordered":false}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Press the <strong>Patch ▲</strong> button to scroll up to Patch <code>64</code>.","Play a note; confirm it produces the raw, unfiltered single-sawtooth tone characteristic of the Init patch.","Scroll through patches <code>65</code> to <code>70</code>; confirm all initialized user slots sound identical."],"ordered":true}]},{"type":"step","title":"3. Self-Assessment Checkpoint","blocks":[{"type":"list","items":["[ ] Which patch slots are factory-populated with the standardized Init patch?","[ ] Are factory patch slots 0–63 permanently write-locked against user modification?"],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-3-2-2","title":"3.2.2: Patch Loading and Edit Buffer Volatility","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Immediate Loading Architecture</strong>:","Pressing <strong>Patch ▲</strong> or <strong>Patch ▼</strong> instantly updates the internal digital control registers and immediately reprograms the analogue hardware.","Holding down either button scrolls through patch numbers rapidly.","<strong>Edit Buffer Volatility</strong>:","Any manual adjustments made to a loaded patch are stored solely in a volatile <strong>edit buffer</strong>.","If you modify a patch (e.g., adjust filter cutoff, oscillator tuning, or envelope decay) and then press <strong>Patch ▲</strong> or <strong>Patch ▼</strong> <em>without first executing a Save operation</em>, <strong>all modifications are instantly and permanently discarded</strong>."],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[Stored Patch Memory] ──► (Load) ──► [Volatile Edit Buffer] ──► (Sound Generated)\n         ▲                                   │\n         │                                   │ (Unsaved Parameter Changes)\n         └─── (Save Twice) ◄─────────────────┘\n                   ▲\n  (Changing Patch Discards Edit Buffer if Unsaved!)</pre>"}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Load Patch <code>0</code>.","Turn the <strong>Filter Frequency</strong> knob to zero (closing the filter completely).","Press <strong>Patch ▲</strong> (moving to Patch <code>1</code>), then immediately press <strong>Patch ▼</strong> (returning to Patch <code>0</code>).","Play a note; observe that Patch <code>0</code> has reloaded its original stored open filter value, and your edit was discarded."],"ordered":true}]},{"type":"step","title":"3. Self-Assessment Checkpoint","blocks":[{"type":"list","items":["[ ] What happens to unsaved knob edits if you switch to a different patch before pressing Save?"],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-3-2-3","title":"3.2.3: Saving to the Current Patch Slot","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"To write the contents of the volatile edit buffer directly back into the current patch memory slot:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[Step 1: Press SAVE] ──► Display Flashes Active Patch Number (e.g., \"0\")\n[Step 2: Press SAVE] ──► Memory Written; Display Stops Flashing; Edits Locked</pre>"},{"type":"list","items":["Press the <strong>Save</strong> button once. The active patch number begins flashing rapidly on the 3-character LED display.","While the display is flashing, press <strong>Save</strong> a second time.","The display stops flashing, confirming that the new parameter values are written to non-volatile flash memory."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Navigate to user slot <code>100</code>.","Select the <strong>Square</strong> waveform in the Oscillator section.","Press <strong>Save</strong> (display flashes <code>100</code>).","Press <strong>Save</strong> again (display stops flashing).","Switch to patch <code>101</code>, then switch back to <code>100</code>; verify the Square waveform is preserved."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-3-2-4","title":"3.2.4: Saving to an Alternate Patch Slot","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"To save a modified patch to a <em>different</em> memory location (e.g., preserving a factory sound while saving your customized version into a user slot):"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[Step 1: Modify Sound on Patch A (e.g., \"5\")]\n[Step 2: Press SAVE] ──► Display Flashes \"5\"\n[Step 3: Press Patch ▲/▼ to select Target Slot (e.g., \"65\")] ──► Audition Active!\n[Step 4: Press SAVE] ──► Sound Written to Slot \"65\"; Slot \"5\" Remains Untouched</pre>"},{"type":"list","items":["With your customized sound active in the edit buffer, press <strong>Save</strong> once (the source patch number flashes).","Use the <strong>Patch ▲</strong> or <strong>Patch ▼</strong> buttons to scroll to the desired destination slot (e.g., slot <code>65</code>).","<em>Audition Feature</em>: While scrolling to the destination slot, you can play the keyboard to audition the sound currently stored in that destination slot to ensure you do not overwrite an important patch.","Press <strong>Save</strong> a second time to commit the write to the target slot."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Load Factory Patch <code>2</code>. Adjust the <strong>Resonance</strong> knob to maximum.","Press <strong>Save</strong> (display flashes <code>2</code>).","Press <strong>Patch ▲</strong> repeatedly until the display shows <code>65</code>.","Press <strong>Save</strong> again.","Reload Patch <code>2</code> (confirming it retains its original factory resonance) and load Patch <code>65</code> (confirming it contains your high-resonance variation)."],"ordered":true}]},{"type":"step","title":"3. Self-Assessment Checkpoint","blocks":[{"type":"list","items":["[ ] Can you audition the destination patch before confirming the save operation?","[ ] How do you commit the final save once the target slot number is selected?"],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-3-2-5","title":"3.2.5: Aborting a Save Operation","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"If you initiate a save operation by accident, or decide not to overwrite a selected memory slot:"},{"type":"list","items":["While the display is flashing the patch number, press the <strong>Function / Exit</strong> button.","The save routine terminates immediately without writing any data to non-volatile memory, and the display returns to its steady state."],"ordered":false}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["On any patch, press <strong>Save</strong> so the display begins flashing.","Press <strong>Function / Exit</strong>.","Confirm that the display ceases flashing and returns to standard play mode without altering any memory registers."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-3-2-6","title":"3.2.6: Factory Preset Restoration Awareness","blocks":[{"type":"step","title":"3.2.6: Factory Preset Restoration Awareness","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"prose","html":"Because patch slots <code>0</code> through <code>63</code> can be overwritten by user sound design, Novation provides several recovery paths:"},{"type":"list","items":["<strong>Novation Components Librarian</strong>: Connecting via USB allows individual factory patches or the entire 64-patch factory bank to be restored into slots 0–63 with a single click.","<strong>Standard MIDI SysEx File</strong>: A standard <code>.syx</code> bank file containing the factory soundset can be transmitted from any DAW or SysEx utility (e.g., MIDI-OX or Snoize SysEx Librarian) to restore factory defaults."],"ordered":true}]},{"type":"step","title":"Section 3.3 — Performance Basics on Day One","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Operate the Pitch and Modulation wheels with proper physical technique and destination awareness.","Execute keyboard octave shifting across the full −5 to +4 range and perform instant octave reset.","Apply semitone transposition relative to Middle C.","Engage the arpeggiator engine at a foundational level."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-3-3-1","title":"3.3.1: Pitch Bend Wheel Operation","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Mechanical Mechanism</strong>:","The Pitch Wheel is spring-loaded and returns to the center-detent position (value 0) when released.","Pushing the wheel forward bends pitch upwards; pulling the wheel downward bends pitch downwards.","<strong>Default &amp; Programmable Range</strong>:","Default bend range is <strong>12 semitones</strong> (one full octave up and down).","Pitch bend range can be configured independently for positive and negative directions across a range of <strong>−24 to +24 semitones</strong> using the On-Key <strong>Pitch Bend Range</strong> function."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Strike and hold Middle C on an initialized patch.","Push the Pitch Wheel fully forward; verify that the pitch rises exactly one octave (to C4).","Release the wheel; verify pitch snaps back to Middle C instantly.","Pull the wheel fully downward; verify pitch drops exactly one octave (to C2)."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-3-3-2","title":"3.3.2: Modulation Wheel Operation and Destination Routing","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Mechanical Mechanism</strong>:","The Modulation Wheel is friction-mounted, retaining any position to which it is moved.","It is backlit with an internal LED that illuminates in proportion to wheel position.","<strong>Standard Routing &amp; MIDI CC 1</strong>:","Transmits standard MIDI Continuous Controller <strong>CC 1</strong> (range 0 to 127).","In factory presets, the Mod Wheel is typically assigned to introduce LFO 1 pitch vibrato or open the filter cutoff.","Specific Mod Wheel routing depths are assigned via On-Key functions:","<strong>Mod Wh: Filter Freq</strong> (Upper keybed notes)","<strong>Mod Wh: LFO 1 to Osc Pitch</strong>","<strong>Mod Wh: LFO 2 to Filter Freq</strong>","<strong>Mod Wh: Osc 2 Pitch</strong>"],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Load Factory Patch <code>0</code> or <code>1</code>.","Play a sustained note and push the Mod Wheel forward.","Observe the internal LED brighten and hear the programmed modulation effect engage."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-3-3-3","title":"3.3.3: Octave Shift and Dual-Button Reset","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Keyboard Span</strong>:","The physical keybed contains 25 keys spanning two octaves (<strong>C2 to C4</strong> when Octave shift is set to <code>0</code>).","Lowest physical key at Octave <code>0</code> is <strong>one octave below Middle C (C2)</strong>; highest key is <strong>one octave above Middle C (C4)</strong>.","<strong>Octave Shift Range</strong>:","<strong>Octave ▲</strong>: Shifts keyboard pitch upwards by up to <strong>+4 octaves</strong>.","<strong>Octave ▼</strong>: Shifts keyboard pitch downwards by up to <strong>−5 octaves</strong>.","Combined with the 2-octave physical keybed, this covers the complete 10-octave MIDI note spectrum (C-2 to G8).","<strong>Instant Reset</strong>:","Pressing <strong>Octave ▲ and Octave ▼ simultaneously</strong> instantly resets the octave shift to <code>0</code>."],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                  OCTAVE SHIFT PHYSICAL LOGIC\n        ┌─────────────┐                      ┌─────────────┐\n        │  OCTAVE ▲   │                      │  OCTAVE ▼   │\n        └──────┬──────┘                      └──────┬──────┘\n               │                                    │\n               └───────────► [BOTH TOGETHER] ◄──────┘\n                                    │\n                                    ▼\n                         Instant Reset to Octave 0</pre>"}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Press <strong>Octave ▼</strong> three times. Display briefly confirms <code>-3</code>.","Strike the lowest key; verify deep sub-bass frequencies.","Press both <strong>Octave ▲ and ▼</strong> simultaneously. Display confirms <code>0</code>."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-3-3-4","title":"3.3.4: Semitone Transposition Architecture","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Transposition Logic</strong>:","The Bass Station II allows global semitone transposition relative to <strong>Middle C (the middle C key on the 25-note keybed)</strong>.","<strong>Execution Gesture</strong>:","Press and hold the <strong>Transpose</strong> button.","While holding Transpose, press any key on the keybed:","Pressing a key <em>above</em> Middle C transposes pitch upwards by the corresponding semitone interval.","Pressing a key <em>below</em> Middle C transposes pitch downwards by the corresponding semitone interval.","Pressing <strong>Middle C</strong> resets transposition to standard pitch.","<strong>Display Feedback</strong>:","The display momentarily indicates the semitone offset (e.g., <code>1</code> for +1 semitone, <code>-2</code> for -2 semitones, <code>0</code> for neutral)."],"ordered":true}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Hold <strong>Transpose</strong> and press <code>D</code> above Middle C. Display confirms <code>2</code> (transposed up a major second).","Play <code>C</code>; confirm it now sounds as <code>D</code>.","Hold <strong>Transpose</strong> and press Middle C. Display confirms <code>0</code>; pitch returns to standard tuning."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-3-3-5","title":"3.3.5: Foundational Arpeggiator Engagement","blocks":[{"type":"step","title":"3.3.5: Foundational Arpeggiator Engagement","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"list","items":["<strong>Basic Activation</strong>:","Press the <strong>On</strong> button in the Arp section (LED illuminates).","<strong>Tempo &amp; Rhythm</strong>:","Rotate <strong>Tempo</strong> to adjust arpeggiation speed (40–240 BPM).","Set <strong>Rhythm</strong> to <code>1</code> (straight quarter/eighth note clock division).","Set <strong>Mode</strong> to <code>Up</code>.","<strong>Chord Arpeggiation</strong>:","Holding down a three-note chord (e.g., C-E-G) causes the engine to cycle sequentially through the notes.","<strong>Latch</strong>:","Press <strong>Latch</strong>; release the keys. The arpeggio continues playing indefinitely until Latch or On is disengaged."],"ordered":true}]},{"type":"step","title":"Assessment Gate B — Self-Assessment Checkpoint","blocks":[{"type":"prose","html":"Before advancing to Module 4, verify that you can execute all Gate B proficiencies:"},{"type":"list","items":["[ ] <strong>Audio Path</strong>: Establish a clean audio output path via Line Out and Headphones without acoustic distortion.","[ ] <strong>Patch Navigation</strong>: Navigate freely between Factory Presets (0–63) and User Init slots (64–127).","[ ] <strong>Save Routine</strong>: Modify a patch parameter, execute a safe write into User Slot <code>100</code>, and reload it to prove non-volatile retention.","[ ] <strong>Save Abort</strong>: Initiate a save sequence and successfully abort it with the Function/Exit button without altering memory.","[ ] <strong>Performance Gestures</strong>: Execute octave shifts, dual-button octave reset, and semitone transposition from memory."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
